 const singleComment = Symbol('singleComment');
 const multiComment = Symbol('multiComment');

 export default function stripJsonComments(jsonString: string) {
 	if (typeof jsonString !== 'string') {
 		throw new TypeError(`Expected argument \`jsonString\` to be a \`string\`, got \`${typeof jsonString}\``);
 	}

 	let result = '';
 	let isInsideString = false;
 	let isInsideComment: symbol | boolean = false;
 	let isEscapedCharacter = false;

 	for (let index = 0; index < jsonString.length; index++) {
 		const currentCharacter = jsonString[index];
 		const nextCharacter = jsonString[index + 1];

 		if (isInsideString) {
 			result += currentCharacter;

 			if (isEscapedCharacter) {
 				isEscapedCharacter = false;
 			} else if (currentCharacter === '\\') {
 				isEscapedCharacter = true;
 			} else if (currentCharacter === '"') {
 				isInsideString = false;
 			}

 			continue;
 		}

 		if (isInsideComment === singleComment) {
 			if (currentCharacter + nextCharacter === '\r\n') {
 				result += currentCharacter + nextCharacter;
 				index++;
 				isInsideComment = false;
 			} else if (currentCharacter === '\n' || currentCharacter === '\r') {
 				result += currentCharacter;
 				isInsideComment = false;
 			}

 			continue;
 		}

 		if (isInsideComment === multiComment) {
 			if (currentCharacter + nextCharacter === '*/') {
 				index++;
 				isInsideComment = false;
 			} else if (currentCharacter + nextCharacter === '\r\n') {
 				result += currentCharacter + nextCharacter;
 				index++;
 			} else if (currentCharacter === '\n' || currentCharacter === '\r') {
 				result += currentCharacter;
 			}

 			continue;
 		}

 		if (currentCharacter === '"') {
 			isInsideString = true;
 			result += currentCharacter;
 			continue;
 		}

 		if (currentCharacter + nextCharacter === '//') {
 			isInsideComment = singleComment;
 			index++;
 			continue;
 		}

 		if (currentCharacter + nextCharacter === '/*') {
 			isInsideComment = multiComment;
 			index++;
 			continue;
 		}

 		result += currentCharacter;
 	}

 	return stripTrailingCommas(result);
 }

 function stripTrailingCommas(jsonString: string) {
 	let result = '';
 	let isInsideString = false;
 	let isEscapedCharacter = false;

 	for (let index = 0; index < jsonString.length; index++) {
 		const currentCharacter = jsonString[index];

 		if (isInsideString) {
 			result += currentCharacter;

 			if (isEscapedCharacter) {
 				isEscapedCharacter = false;
 			} else if (currentCharacter === '\\') {
 				isEscapedCharacter = true;
 			} else if (currentCharacter === '"') {
 				isInsideString = false;
 			}

 			continue;
 		}

 		if (currentCharacter === '"') {
 			isInsideString = true;
 			result += currentCharacter;
 			continue;
 		}

 		if (currentCharacter === ',') {
 			let nextIndex = index + 1;
 			while (/\s/.test(jsonString[nextIndex] ?? '')) {
 				nextIndex++;
 			}

 			if (jsonString[nextIndex] === '}' || jsonString[nextIndex] === ']') {
 				continue;
 			}
 		}

 		result += currentCharacter;
 	}

 	return result;
 }

